const data = $input.first().json;
const matches = data.tennis || [];
const filtered = [];

for (const match of matches) {
  const status = (match.status || '').toLowerCase();
  const eventId = match.eventId || match.matchId?.replace('TENNIS-', '');
  if (eventId && status !== 'finished' && status !== 'ended' && status !== 'cancelled' && status !== 'walkover') {
    filtered.push({
      json: {
        matchId: match.matchId,
        eventId: String(eventId),
        player1: match.player1,
        player2: match.player2,
        status: match.status
      }
    });
  }
}

if (filtered.length === 0) {
  return [{ json: { scores: [], message: 'No pending tennis matches to update' } }];
}

return filtered;

// Cross pending DB matches with api-tennis results by event_key.
const feed = $input.first().json || {};
const events = Array.isArray(feed.result) ? feed.result : [];
const pendingItems = $('Filter Pending Matches').all();

const byKey = {};
for (const ev of events) { byKey[String(ev.event_key)] = ev; }

function finalSets(ev) {
  const fr = (ev.event_final_result || '').trim();
  const m2 = fr.match(/^(\d+)\s*-\s*(\d+)$/);
  if (m2) return [parseInt(m2[1]), parseInt(m2[2])];
  let s1 = 0, s2 = 0;
  for (const s of (Array.isArray(ev.scores) ? ev.scores : [])) {
    const a = parseInt(s.score_first) || 0;
    const b = parseInt(s.score_second) || 0;
    if (a > b) s1++; else if (b > a) s2++;
  }
  return [s1, s2];
}

function pointsPerSet(ev) {
  // Per-set points from statistics ("Total Points Won", stat_period set1/set2/...).
  const stats = Array.isArray(ev.statistics) ? ev.statistics : [];
  if (!stats.length) return [];
  const p1Key = String(ev.first_player_key || '');
  const bySet = {};
  for (const s of stats) {
    if (s.stat_name !== 'Total Points Won' || s.stat_won == null) continue;
    const m2 = /^set(\d+)$/.exec(String(s.stat_period || ''));
    if (!m2) continue;
    const idx = m2[1];
    bySet[idx] = bySet[idx] || {};
    bySet[idx][String(s.player_key) === p1Key ? 'p1' : 'p2'] = Number(s.stat_won) || 0;
  }
  return Object.keys(bySet).sort().map(k => ({ set: Number(k), p1: bySet[k].p1 ?? 0, p2: bySet[k].p2 ?? 0 }));
}

function matchAces(ev) {
  // Match-level aces per player from statistics (stat_name "Aces", period "match").
  const stats = Array.isArray(ev.statistics) ? ev.statistics : [];
  const p1Key = String(ev.first_player_key || '');
  let home = null, away = null;
  for (const s of stats) {
    if (s.stat_name !== 'Aces' || s.stat_period !== 'match' || s.stat_value == null) continue;
    const v = parseInt(s.stat_value);
    if (isNaN(v)) continue;
    if (String(s.player_key) === p1Key) home = v; else away = v;
  }
  return (home == null || away == null) ? null : { home, away };
}

function serveStats(ev) {
  // Serve/return game counts and 1st/2nd serve point counts per player (period "match").
  const stats = Array.isArray(ev.statistics) ? ev.statistics : [];
  if (!stats.length) return null;
  const p1Key = String(ev.first_player_key || '');
  const out = { home: {}, away: {} };
  const fields = {
    'Service games won': ['serveGamesWon', 'serveGamesTotal'],
    'Return games won': ['returnGamesWon', 'returnGamesTotal'],
    '1st serve points won': ['firstServeWon', 'firstServeTotal'],
    '2nd serve points won': [null, 'secondServeTotal'],
    'Service Points Won': [null, 'servePtsTotal']
  };
  for (const s of stats) {
    if (s.stat_period !== 'match') continue;
    const f = fields[s.stat_name];
    if (!f) continue;
    const side = String(s.player_key) === p1Key ? 'home' : 'away';
    if (f[0] && s.stat_won != null) out[side][f[0]] = Number(s.stat_won);
    if (f[1] && s.stat_total != null) out[side][f[1]] = Number(s.stat_total);
  }
  return (out.home.serveGamesTotal != null && out.away.serveGamesTotal != null) ? out : null;
}

const scores = [];
for (const item of pendingItems) {
  const m = item.json || {};
  if (!m.eventId) continue;
  const ev = byKey[String(m.eventId)];
  if (!ev) continue;
  const st = (ev.event_status || '').toLowerCase();
  const isFinished = st === 'finished' || st === 'ended';
  const isDead = st === 'retired' || st === 'walkover' || st === 'cancelled';
  if (!isFinished && !isDead) continue;
  const [s1, s2] = finalSets(ev);
  const item = {
    matchId: m.matchId,
    homeScore: s1,
    awayScore: s2,
    status: isFinished ? 'FINISHED' : 'CANCELLED'
  };
  // Per-set games (for tournament load / fatigue stats)
  const setRows = (Array.isArray(ev.scores) ? ev.scores : [])
    .map(s => ({ p1: parseInt(s.score_first) || 0, p2: parseInt(s.score_second) || 0 }))
    .filter(r => r.p1 || r.p2);
  if (isFinished && setRows.length) {
    item.extraData = { sets: setRows };
    const pointRows = pointsPerSet(ev);
    if (pointRows.length) item.extraData.points = pointRows;
    const aces = matchAces(ev);
    if (aces) { item.extraData.homeAces = aces.home; item.extraData.awayAces = aces.away; }
    const serve = serveStats(ev);
    if (serve) item.extraData.serve = serve;
  }
  scores.push(item);
}
return [{ json: { scores, count: scores.length } }];

const scoresData = $('Build Scores Payload').first().json;
const dbResult = $input.first().json || {};
const count = scoresData.count || 0;
const inserted = dbResult.inserted || 0;
const updated = dbResult.updated || 0;
const errors = dbResult.errors ? dbResult.errors.length : 0;
const message = count === 0 ? 'No hay partidos de tenis finalizados para actualizar.' : `Actualizados ${count} partidos de tenis finalizados.`;
const telegramMessage = `<b>BrainBets - Scores de Tenis</b>\n\n${message}\nInsertados: ${inserted}\nActualizados: ${updated}\nErrores: ${errors}`;
return [{
  json: {
    telegramMessage: telegramMessage,
    dbResult: dbResult,
    scoresCount: count
  }
}];
